INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a3c2b1a6cf242bf4514a4d6934756f84abb3c1ce/content/books/zizhi-tongjian/vol-293/year-0957/part-01/sources/library/jiuwudaishi-117-february-957/source.txt", "note": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002767；EPUB电子本，纸本及异文待核", "id": "93908c1f-1470-522d-93ba-e38cf3c284c0"}, {"title": "旧五代史·卷一百十七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a3c2b1a6cf242bf4514a4d6934756f84abb3c1ce/content/books/zizhi-tongjian/vol-293/year-0957/part-01/sources/library/jiuwudaishi-117-january-957/source.txt", "note": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002766；EPUB电子本，纸本及异文待核", "id": "587f0ef1-92bf-5eb8-9c0d-e25220dafd0a"}, {"title": "宋史·巻四百三十一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a3c2b1a6cf242bf4514a4d6934756f84abb3c1ce/content/books/zizhi-tongjian/vol-293/year-0957/part-01/sources/library/songshi-431-niechongyi-ritual/source.txt", "note": "《宋史》巻四百三十一，段落 songshi-9c6e46fee832-p070842；EPUB电子本，纸本及异文待核", "id": "1faa34c2-cf8b-534c-82ac-5eb8166a1a26"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a3c2b1a6cf242bf4514a4d6934756f84abb3c1ce/content/books/zizhi-tongjian/vol-293/year-0957/part-01/sources/library/tongjian-293-957-february-march/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003481；电子底本待考，分段待核", "id": "d48b53b3-0246-5fbb-9456-5d402d58c83f"}, {"title": "新五代史·卷三十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a3c2b1a6cf242bf4514a4d6934756f84abb3c1ce/content/books/zizhi-tongjian/vol-293/year-0957/part-01/sources/library/xinwudaishi-32-liuchongjian/source.txt", "note": "《新五代史》卷三十二，段落 xin-wudaishi-b08f244b9241-p001163；EPUB电子本，纸本及异文待核", "id": "328f9899-24fb-506e-a860-315a7ca2d101"}, {"title": "新五代史·卷七十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a3c2b1a6cf242bf4514a4d6934756f84abb3c1ce/content/books/zizhi-tongjian/vol-293/year-0957/part-01/sources/library/xinwudaishi-70-tianhui-era/source.txt", "note": "《新五代史》卷七十，段落 xin-wudaishi-b08f244b9241-p003455；EPUB电子本，纸本及异文待核", "id": "6141462a-c62b-50df-8c9d-ce22db042154"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/46f543ceeb3df4fc512bb882ee567e6a76892890/content/books/zizhi-tongjian/vol-293/year-0956/part-07/sources/library/tongjian-293-956-year-end/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003480；电子底本待考，分段待核", "id": "5e5f3333-c0c8-5644-977c-487cfa039e75"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘承钧", "aliases": ["劉承鈞", "刘钧", "劉鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的次子。951年父亲在晋阳称帝时，任侍卫亲军都指挥使、太原尹。《旧五代史》也记他是刘崇之子并任两职。生卒年本批未录。", "biography": null, "status": "draft", "id": "3f4681a7-ca79-5d5d-a5c2-53bef1936681"}, {"name": "卫融", "aliases": ["衛融"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉官员，青州博兴人，字明远。951年七月以翰林学士身份奉刘崇之命出使契丹，谢册礼并请求援兵。《宋史》记早年中进士，曾任南乐主簿、忠武军掌书记等职。生卒年尚未录入。", "biography": null, "status": "draft", "id": "318087c3-dd4d-529d-bf97-fe917d05375b"}, {"name": "段恒", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉内客省使。957年正月获任枢密使。姓名、职务与北汉年条核对，生卒年未载。", "biography": null, "status": "draft", "id": "3a252d74-6649-5176-ac70-7ecc8d19194c"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "许文稹", "aliases": ["許文稹", "许文缜", "許文縝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "同安人，汀州刺史。944年朱文进掌权后率郡投降朱文进。《新五代史》对应汀州守将作許文縝，保留姓名字形异文；该书后文投降王延政为另一阶段，不混为当前投降对象。生卒年未载。", "biography": null, "status": "draft", "id": "6717f767-1ab2-52b8-8015-c778cc06ee45"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "舒元", "aliases": ["朱元", "硃元"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沈丘人，早先以游士身份投靠李守贞。李守贞被后汉围攻后，让他改姓朱，赴南唐求援。《新五代史》记求援者为朱元。生卒年尚未确定。", "biography": null, "status": "draft", "id": "4747ce90-dd4b-5e0b-a0c8-7420788a2347"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "刘仁赡", "aliases": ["劉仁贍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领，刘金之子，字守惠、彭城人。951年以武昌节度使身份率二百艘战舰攻取岳州。《新五代史》还记他早年任左监门卫将军、黄袁二州刺史，后掌亲军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "fbdf8a53-b985-5dda-a5d1-e96cf9d7121c"}, {"name": "刘崇谏", "aliases": ["劉崇諫", "崇谏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐寿州守将刘仁赡的幼子。《资治通鉴》记其夜渡淮北被捕，父亲命处以腰斩；《新五代史》记其趁父病谋与诸将出降。原书对前因记载不同，处刑具体日未载。", "biography": null, "status": "draft", "id": "7aa34f85-1464-52c9-940d-9f39ca64bfe9"}, {"name": "周廷构", "aliases": ["周廷構"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐寿州监军使。957年刘崇谏被父亲下令处死时，先哭求刘仁赡，又求其夫人相救，未获允许。生卒年未载。", "biography": null, "status": "draft", "id": "d7ac22dd-cc9c-5a26-a87e-55a75330cee8"}, {"name": "刘仁赡妻（姓名未载）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐刘仁赡的夫人，姓名未载。刘崇谏被下令处死时，周廷构向她求救，她认为军法名节不可徇私，催行处刑后才办理丧事。此条未明确其是否为崇谏生母，不建立母子关系。", "biography": null, "status": "draft", "id": "71212d60-b231-523b-9b0c-57cba6f52fee"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "王溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262天复元年条所见人物：王溥。", "biography": null, "status": "draft", "id": "b8b4ff87-1c1f-5c80-bc6c-83b5a3b1164f"}, {"name": "聂崇义", "aliases": ["聶崇義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河南洛阳人，研习礼学，后汉乾祐年间任国子礼记博士。957年柴荣命其研究祭器祭玉制度、绘图呈报。《宋史》补载其在该年上图，朝廷另造祭器。生卒年未载。", "biography": null, "status": "draft", "id": "c6186181-2e72-5ce6-820a-cf540b729926"}, {"name": "王朴", "aliases": ["王樸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "东平人，原任校书郎。951年任柴荣镇宁军掌书记。《旧五代史》记他字文伯，在后汉乾祐年间中进士，后来进入澶州幕府。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aef64c13-19ef-556c-96f1-dd9e8fb91844"}, {"name": "张美", "aliases": ["張美"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "清河人，后周枢密院承旨。《通鉴》记955年六月任右领军大将军、权点检三司事，《旧五代史》记八月任权判三司，任职月与称号差异分别保留。早年管理澶州隶属三司的财物，曾应柴荣私人所求而供给，郭威得知后将他调到濮州。", "biography": null, "status": "draft", "id": "e0ae365f-4a51-5f92-82eb-86e617f0d42b"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "王环（后蜀凤州节度使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "镇州真定人，早年以勇力为孟知祥御者，后掌后蜀宿卫。开运末秦凤等地入蜀后，孟昶任其为凤州节度使。955年十一月凤州陷落时被后周军俘获。与914—929年楚水军将领王环分别保存，无同人证据。生卒年未载。", "biography": null, "status": "draft", "id": "abfc7768-1b27-5f09-bc3e-db6360a31dd2"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "北汉大赦并改元天会", "start_year": 957, "end_year": 957, "time_original": "957年正月己丑朔", "dynasty": "五代十国", "description": "北汉大赦并改元天会。", "phases": [], "location_name": "北汉", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b4bb5d80-380d-58a6-a7cf-40b08db3b53c"}, {"title": "刘承钧任卫融为中书侍郎、同平章事", "start_year": 957, "end_year": 957, "time_original": "957年正月己丑朔条所记", "dynasty": "五代十国", "description": "刘承钧任卫融为中书侍郎、同平章事。", "phases": [], "location_name": "北汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "833d9057-535f-5b02-bc35-f0a9b1e58f8a"}, {"title": "刘承钧任段恒为枢密使", "start_year": 957, "end_year": 957, "time_original": "957年正月己丑朔条所记", "dynasty": "五代十国", "description": "刘承钧任段恒为枢密使。", "phases": [], "location_name": "北汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "675749cc-ab78-5738-890d-5d343b2e2bb8"}, {"title": "柴荣认为功臣子弟尚未受恩，不宜先封幼子为王", "start_year": 957, "end_year": 957, "time_original": "957年正月条所记，具体日未载", "dynasty": "五代十国", "description": "柴荣认为功臣子弟尚未受恩，不宜先封幼子为王。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "72e0423d-d87a-5fe7-8e03-6b7cfcd7f8b0"}, {"title": "寿春被围连年未下，城中粮食耗尽", "start_year": 957, "end_year": 957, "time_original": "957年正月援军行动前的围城状态", "dynasty": "五代十国", "description": "寿春被围连年未下，城中粮食耗尽。", "phases": [], "location_name": "寿春", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0f73e607-32eb-5b18-8c24-7845cd5e8f73"}, {"title": "徐景达派许文稹、边镐、朱元援寿春，在紫金山设营", "start_year": 957, "end_year": 957, "time_original": "957年正月丁未奏报前，具体进军日未载", "dynasty": "五代十国", "description": "徐景达派许文稹、边镐、朱元率数万兵溯淮援寿春，在紫金山列十余寨，如连珠相接，与城内早晚用烽火呼应。数万、十余为史载概数，朱元复用此前改姓的舒元，许文稹与许文缜姓名异文沿既有记录。", "phases": [], "location_name": "濠州沿淮至紫金山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b26cf7d2-82a6-5ab7-b16c-715c9c587ba0"}, {"title": "南唐援军筑甬道，计划向寿春运粮", "start_year": 957, "end_year": 957, "time_original": "957年正月李重进截击前，具体日未载", "dynasty": "五代十国", "description": "南唐援军筑甬道，计划向寿春运粮。", "phases": [], "location_name": "紫金山至寿春", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d310748a-c5ca-5cbf-b3fd-dabb4d5e09d4"}, {"title": "李重进截击寿春援军，夺两寨并奏报", "start_year": 957, "end_year": 957, "time_original": "957年正月丁未奏报；具体战斗日未载", "dynasty": "五代十国", "description": "南唐援军将近寿春时被李重进截击。《资治通鉴》记大破援军、死亡五千人、夺两寨，李重进于丁未奏报。《旧五代史》记在寿州北破敌五千人，两书的死亡与破敌口径分别保留。", "phases": [], "location_name": "寿春附近", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "87c173b1-75af-5375-a579-75ffd0860eed"}, {"title": "柴荣诏告下月亲往淮上", "start_year": 957, "end_year": 957, "time_original": "957年正月戊申下诏，计划二月出行", "dynasty": "五代十国", "description": "柴荣诏告下月亲往淮上。", "phases": [], "location_name": "后周朝廷至淮上", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2d9039ca-a1ae-54df-b491-520b6c413292"}, {"title": "刘仁赡请让边镐守城、自己出战，徐景达不准", "start_year": 957, "end_year": 957, "time_original": "957年正月寿春援军阶段，具体日未载", "dynasty": "五代十国", "description": "刘仁赡请让边镐守城、自己出战，徐景达不准。", "phases": [], "location_name": "寿春与南唐援军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2004beaa-4b26-5636-b528-fa348381b4ea"}, {"title": "刘崇谏夜渡淮北被捕，刘仁赡命处以腰斩", "start_year": 957, "end_year": 957, "time_original": "957年寿春守城条所记，具体夜间日期未载", "dynasty": "五代十国", "description": "《资治通鉴》记刘仁赡幼子刘崇谏夜间乘船渡淮北，被小校捕获，刘仁赡命腰斩，左右不敢营救。该句没有明写已经投降后周；《新五代史》另记他趁父亲病重谋与诸将出降，前因分别保留。", "phases": [], "location_name": "寿春及淮河北岸", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "db8af8c0-72c4-5d8d-82e3-8645b34a997e"}, {"title": "周廷构哭求刘仁赡救刘崇谏，未获准", "start_year": 957, "end_year": 957, "time_original": "957年刘崇谏处刑之前，具体日未载", "dynasty": "五代十国", "description": "周廷构哭求刘仁赡救刘崇谏，未获准。", "phases": [], "location_name": "寿春中门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ae2e80e3-ac00-5bba-a821-968075692c32"}, {"title": "刘仁赡夫人拒绝救子请求，催处刑后才办丧事", "start_year": 957, "end_year": 957, "time_original": "957年刘崇谏处刑时，具体日未载", "dynasty": "五代十国", "description": "周廷构又派人向刘仁赡夫人求救。她称并非不爱崇谏，但军法、名节不能徇私，否则刘氏将成为不忠之家，催促执行死刑，然后才办丧事。《通鉴》称将士感泣，这是史书记载的评价与反应，不编造在场全员名单。", "phases": [], "location_name": "寿春", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "24b46e0e-d186-5503-aafb-3d6370faaf6b"}, {"title": "有人以南唐援军仍强请求罢兵，柴荣犹疑", "start_year": 957, "end_year": 957, "time_original": "957年二月丙寅问策前，具体日未载", "dynasty": "五代十国", "description": "有人以南唐援军仍强请求罢兵，柴荣犹疑。", "phases": [], "location_name": "后周朝廷及李谷家中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "96ffa722-b6f5-55f7-8c75-2c3057ee35f6"}, {"title": "柴荣派范质、王溥问计病中的李谷，李谷建议亲征", "start_year": 957, "end_year": 957, "time_original": "957年二月丙寅", "dynasty": "五代十国", "description": "柴荣派范质、王溥到病中的李谷家商议。李谷上疏认为寿春已危困，皇帝亲征可振奋将士、震慑援军，促城内认清败局，柴荣阅后欣悦。必可下是李谷预测，不把建议当成本日已经攻克寿春。", "phases": [], "location_name": "后周朝廷与李谷家中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "345b7a3d-86ee-59da-aefe-8cc1ae26442f"}, {"title": "柴荣命聂崇义研究祭器、祭玉制度并绘图", "start_year": 957, "end_year": 957, "time_original": "957年二月庚午", "dynasty": "五代十国", "description": "柴荣命聂崇义研究祭器、祭玉制度并绘图。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5cf09ece-29ed-5c68-8e33-3100079123da"}, {"title": "聂崇义于显德四年呈交祭器图，朝廷命另造祭器", "start_year": 957, "end_year": 957, "time_original": "《宋史》显德四年（957年），具体呈图日未载", "dynasty": "五代十国", "description": "聂崇义于显德四年呈交祭器图，朝廷命另造祭器。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b4a9118c-f7b0-502e-805e-f409c1b55edc"}, {"title": "柴荣命王朴权东京留守、判开封府", "start_year": 957, "end_year": 957, "time_original": "957年二月甲戌", "dynasty": "五代十国", "description": "柴荣命王朴权东京留守、判开封府。", "phases": [], "location_name": "东京开封", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "89e3fbc0-b165-5bea-ab5e