cision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "51be2166-2197-5910-8e3e-1f710b83631c"}, {"title": "王环率数千周军水师自闵河沿颍入淮", "start_year": 957, "end_year": 957, "time_original": "957年二月再次亲征时，具体发船日未载", "dynasty": "五代十国", "description": "王环率数千周军水师自闵河沿颍入淮。", "phases": [], "location_name": "闵河沿颍水至淮河", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "54cdec34-8654-5c66-9953-298ab7caa087"}]'::jsonb)
